import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
FRZ="Instructions de congélation : "
recs=[
R(7882491,"Pâté de haricots beurre","Un appétissant dip de haricots beurre à l'oignon nouveau, au concombre et à la menthe, servi avec des bâtonnets de légumes croquants.","4","209 g",
["1 boîte de 400 g de haricots beurre, égouttés (240 g)","4 oignons nouveaux, finement hachés (50 g)","6 cm de concombre, coupé en très petits dés (80 g)","2 c. à soupe de yaourt nature non sucré","1 gousse d'ail, écrasée","1 c. à soupe d'huile d'olive extra vierge","jus et zeste d'un demi-citron","3 brins de menthe fraîche, hachés","1 bonne pincée de poivre","1 pincée de paprika","4 tomates cerises","1 branche de céleri, coupée en bâtonnets","½ bulbe de fenouil, coupé en bâtonnets","1 grosse carotte, coupée en bâtonnets","1 poivron jaune, coupé en bâtonnets","crudités variées"],
["Écrasez soigneusement la moitié des haricots à la fourchette jusqu'à obtenir une texture assez lisse. Écrasez légèrement l'autre moitié, puis mélangez les deux.","Incorporez les oignons nouveaux, le concombre, le yaourt, l'ail, l'huile d'olive, le citron, la menthe et le poivre, puis réservez.","Pendant ce temps, préparez les bâtonnets de légumes à tremper.","Remélangez le pâté, saupoudrez de paprika et servez."],
["Convient bien avec des haricots cannellini ou des haricots blancs. Pour une version végétalienne, utilisez une alternative végétale au yaourt.","Relevez-le avec une cuillère à café de pâte de curry. Vous pouvez utiliser n'importe quels légumes pour tremper : choisissez des couleurs variées pour que le plat reste attrayant.",FRZ+"le dip peut être congelé. Décongelez au réfrigérateur et utilisez immédiatement.","Les valeurs nutritionnelles ci-dessus incluent la suggestion de présentation avec des crudités.",fv(2)]),
R(7882956,"Burger de dinde","Du hachis de blanc de dinde maigre et un petit pain complet garni de salade en font le burger le plus sain de la ville !","8","258 g",
["1 tranche de pain complet","1 œuf, battu","500 g de hachis de blanc de dinde","1 oignon, finement râpé","2 carottes, finement râpées","4 à 6 gousses d'ail, écrasées","1 pincée de poivre noir","8 petits pains complets, coupés en deux (environ 60 g chacun)","150 g de laitue","4 tomates, finement tranchées","1 oignon, finement émincé"],
["Dans un bol, émiettez le pain et ajoutez-le à l'œuf battu. Réservez en mélangeant de temps en temps, jusqu'à ce que le pain ait absorbé tout l'œuf.","Ajoutez le hachis de dinde, l'oignon, la carotte, l'ail et le poivre à l'œuf et au pain, puis mélangez bien.","Façonnez 8 burgers (environ 8 cm de diamètre et 2½ cm d'épaisseur), déposez-les sur une assiette ou un plateau, couvrez de film alimentaire et placez au réfrigérateur au moins 20 minutes, mais une à deux heures, c'est encore mieux.","Faites griller les burgers 6 à 8 minutes de chaque côté, en veillant à ce qu'ils soient bien cuits.","Faites toaster les petits pains, si vous le souhaitez, et composez vos burgers avec la laitue, la tomate et l'oignon."],
["Relevez vos burgers avec une pincée de flocons de piment ou 1 c. à café de cumin moulu. Ou ajoutez des herbes comme le thym ou le romarin.","Pour une touche festive, ajoutez 1 c. à soupe de canneberges séchées à la préparation des burgers.",FRZ+"peuvent être congelés crus ou cuits. Congelez en portions emballées individuellement, avec du papier sulfurisé entre chaque burger. Décongelez complètement au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce qu'ils soient bien chauds et cuits à cœur.",fv(1)]),
R(7886286,"Petit-déjeuner végétarien au four","Ce petit-déjeuner végétarien copieux vous donnera de l'énergie pour la journée. Il est rapide et facile à préparer et regorge de légumes.","2","368 g",
["4 pressions de spray 1 kcal","2 gros champignons portobello, pieds retirés (80 g chacun)","50 g de pois chiches en conserve, égouttés","½ c. à café de paprika fumé","1 sachet de 200 g de jeunes pousses d'épinards lavées","2 c. à soupe de fromage frais allégé aux herbes","1 petite tomate cœur de bœuf (130 g)","1 c. à café de vinaigre balsamique","1 petit avocat (140 g, poids net)"],
["Préchauffez le four à 200 °C (th. 6). Vaporisez la plaque de cuisson et les champignons de quelques pressions de spray 1 kcal. Posez les champignons debout au centre. Mélangez les pois chiches avec le paprika et parsemez-les sur la plaque. Faites cuire 5 minutes.","Coupez un coin du sachet d'épinards et faites cuire au micro-ondes à puissance maximale 2 minutes. Secouez et faites cuire encore 1 minute, jusqu'à ce que les épinards soient fanés. Laissez refroidir, puis pressez le jus des épinards par le coin coupé. Versez les épinards dans un bol et incorporez le fromage frais. Poivrez.","Placez une tranche de tomate sur chaque champignon, arrosez de balsamique, puis recouvrez d'épinards.","Tranchez l'avocat, disposez les tranches en croisillons sur les épinards et vaporisez légèrement d'huile.","Faites cuire 12 à 15 minutes, jusqu'à ce que l'avocat ramollisse. Répartissez dans les assiettes de service. Parsemez de pois chiches et servez avec un filet de balsamique supplémentaire."],
[fv(4)]),
R(7887932,"Mini-poivrons farcis","Ces canapés colorés et sains sont parfaits pour une fête de Noël.","20","35 g",
["50 g de quinoa","1 gousse d'ail, écrasée","10 g de raisins secs, grossièrement hachés","1 c. à café de cumin moulu","1 oignon nouveau, finement haché","1 c. à soupe de concentré de tomate","jus d'un demi-citron","1 c. à café d'huile","10 mini-poivrons variés","5 tomates cerises, coupées en quatre","75 g de mozzarella allégée, coupée en 10 morceaux","1 c. à café de ciboulette hachée, pour la garniture","1 bon tour de moulin de poivre noir"],
["Préchauffez le four à 180 °C (th. 4).","Rincez le quinoa dans une passoire, puis mettez-le dans une casserole avec 150 ml d'eau. Portez à ébullition, baissez le feu et laissez mijoter doucement 15 minutes. Égouttez l'eau non absorbée et égrenez à la fourchette.","Mettez le quinoa dans un bol avec l'ail, les raisins secs, le cumin, l'oignon nouveau, le concentré de tomate et le jus de citron. Mélangez bien et réservez.","Pendant ce temps, huilez légèrement une plaque de cuisson et coupez les poivrons en deux dans la longueur, en gardant les queues et en retirant les graines.","Répartissez le quinoa uniformément dans les poivrons et garnissez chacun d'un quartier de tomate et d'un petit morceau de mozzarella.","Placez les poivrons sur une plaque de cuisson et faites cuire 10 à 12 minutes, jusqu'à ce que les poivrons aient ramolli et que le fromage ait fondu. Parsemez de ciboulette et d'un tour de moulin de poivre noir."],
["Vous pouvez les assembler la veille et les laisser au réfrigérateur toute la nuit, puis les faire cuire juste avant de les servir.","Vous pouvez ajouter d'autres épices, comme de la poudre de curry, ou utiliser du couscous à la place du quinoa.",FRZ+"congelez par portions, puis décongelez au micro-ondes. Réchauffez jusqu'à ce que ce soit bien chaud, en remuant régulièrement. Consommez immédiatement et jetez les restes.",fv(0)]),
R(7890431,"Légumes verts à l'ail et au piment","Rapide, facile et savoureux ! Cet accompagnement est prêt en 20 minutes, de la poêle à l'assiette. Cette recette a été sélectionnée en partenariat avec Slimming World.","4","228 g",
["Spray de cuisson basses calories","3 gousses d'ail, finement émincées","2 piments rouges, épépinés et grossièrement hachés","1 oignon rouge, finement émincé","2 poivrons verts, épépinés et grossièrement hachés","200 g de brocoli à longue tige, paré","150 g de chou frisé, grossièrement haché","Jus d'1 citron non traité"],
["Vaporisez une grande poêle antiadhésive de quelques pressions de spray de cuisson basses calories et placez-la sur feu moyen-vif. Ajoutez l'ail et les piments et faites revenir 1 minute. Ajoutez l'oignon, les poivrons et le brocoli avec 100 ml d'eau et faites revenir 2 à 3 minutes. Incorporez le chou frisé et faites revenir 2 minutes. Assaisonnez légèrement de poivre noir, ajoutez un filet de jus de citron et servez."],
[fv(2)]),
R(7891265,"Saumon en croûte de sésame et salade de haricots verts","Un plat simple, prêt en moins de 30 minutes.","2","372 g",
["jus d'un demi-citron","2 c. à café d'huile de sésame grillé","2 c. à café de cinq-épices chinois","2 pavés de saumon (environ 120 g chacun)","1 c. à soupe de graines de sésame","1 c. à café d'huile de tournesol","200 g de haricots verts fins, équeutés","2 tomates, hachées","½ petit oignon rouge, finement haché","1 laitue « little gem », finement ciselée","2 c. à café de vinaigre balsamique"],
["Préchauffez le four à 180 °C (th. 4). Mélangez le jus de citron, l'huile de sésame et le cinq-épices chinois dans un bol, puis enrobez-en soigneusement les pavés de saumon.","Posez les pavés de saumon sur une assiette et saupoudrez de graines de sésame. Une fois bien enrobés, placez le saumon sur une plaque de cuisson légèrement huilée avec 1 c. à café d'huile de tournesol. Parsemez le poisson des graines restantes et faites cuire au four 12 à 15 minutes.","Pendant ce temps, faites bouillir les haricots 3 à 4 minutes, puis plongez-les dans de l'eau froide pour les refroidir.","Mélangez les haricots, les tomates, l'oignon et la laitue, et répartissez dans deux assiettes. Effeuillez le saumon par-dessus et arrosez de vinaigre balsamique."],
["Cette recette convient aussi bien avec des filets de maquereau ou des pavés de thon frais.","En saison, vous pouvez utiliser des asperges à la place des haricots verts.","Plonger les haricots verts fins dans l'eau froide arrête la cuisson.",fv(2)]),
R(7891662,"Murgh salun (curry de poulet)","Servez ce plat avec du riz ou du naan pour saucer le délicieux jus, ainsi que des légumes cuits à la vapeur en accompagnement.","6","311 g",
["1 c. à soupe d'huile d'olive","2 gros oignons, hachés","4 gousses d'ail, hachées","1 c. à soupe de gingembre frais, haché","8 tomates, hachées","3 piments verts, finement hachés","1,5 c. à café de piment en poudre","12 petits hauts de cuisse de poulet (75 g chacun)","1,5 c. à café de garam masala","4 c. à soupe de yaourt nature allégé"],
["Chauffez l'huile dans une casserole, ajoutez l'oignon, l'ail et le gingembre et faites revenir jusqu'à ce qu'ils soient légèrement dorés.","Ajoutez les tomates, les piments verts et le piment en poudre, mélangez bien et poursuivez la cuisson jusqu'à ce que l'oignon soit ramolli. Ajoutez 2 c. à soupe d'eau et remuez.","Ajoutez les morceaux de poulet dans la casserole avec le garam masala, le yaourt et 200 ml d'eau, couvrez et laissez mijoter 8 à 10 minutes, jusqu'à ce que le poulet soit cuit."],
["Vous pouvez utiliser des escalopes de dinde ou des blancs de poulet à la place des hauts de cuisse.","Pour une version végétarienne, ajoutez 2 boîtes de 400 g de pois chiches et 250 g de champignons de Paris à la place du poulet.",FRZ+"peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que le plat soit bien chaud à cœur.",fv(1)]),
R(7892992,"Bouchées de polenta aux pommes et aux épices","Ces bouchées de polenta sont une gourmandise idéale pour les buffets et les grignotages de fête.","25","31 g",
["300 ml d'eau bouillante","20 g de sucre","8 pastilles de stévia","1 c. à café bombée de gingembre moulu","1 c. à café bombée de cannelle moulue","½ c. à café rase de clou de girofle moulu","40 g de raisins secs","15 g de zestes d'agrumes confits","100 g de polenta instantanée","1 pomme non épluchée, évidée et râpée","1 œuf, battu","50 ml d'huile de colza","½ c. à café de levure chimique","mini-caissettes de cuisson en papier/aluminium","3 cerises confites, 6 amandes blanchies et 1 c. à café de pignons de pin, pour la garniture"],
["Préchauffez le four à 180 °C (th. 4).","Versez l'eau dans une casserole, avec le sucre, la stévia, le gingembre, la cannelle, le clou de girofle, les raisins secs et les zestes confits. Remuez et portez à ébullition en remuant jusqu'à dissolution du sucre.","Incorporez progressivement la polenta et continuez de remuer 4 à 5 minutes, jusqu'à ce qu'elle ait épaissi, puis retirez du feu.","Dans un bol, mélangez la pomme, l'œuf, l'huile et la levure, puis incorporez vigoureusement à la polenta.","Répartissez dans 25 caissettes et disposez sur une plaque de cuisson. Garnissez chacune d'une demi-cerise confite, d'une amande ou de quelques pignons de pin.","Enfournez et faites cuire 16 à 20 minutes, jusqu'à ce que le dessus soit légèrement doré."],
[]),
R(7895649,"Biscuits d'Halloween","Une version moins sucrée du biscuit du nord de l'Angleterre au pain d'épices et à la farine d'avoine. Ils sont traditionnellement servis pour la nuit des feux de joie et sont idéaux pour Halloween.","24","22 g",
["50 ml d'huile de colza","10 g de mélasse noire (blackstrap)","100 ml de lait écrémé","100 g de farine complète","100 g de farine d'avoine","1 c. à café rase de levure chimique","3 c. à café de gingembre en poudre","1 c. à café de mélange d'épices (mixed spice)","12 c. à café d'édulcorant","1 œuf, battu","1 banane mûre, bien écrasée (environ 100 g)"],
["Préchauffez le four à 150 °C (th. 2). Mettez l'huile, la mélasse et le lait dans une casserole et faites chauffer doucement 2 minutes.","Dans un bol, mélangez la farine, la farine d'avoine, la levure, le gingembre, le mélange d'épices et l'édulcorant. Incorporez l'œuf et la banane écrasée.","Chemisez une plaque de cuisson de 30 cm x 20 cm de papier sulfurisé. Incorporez délicatement le mélange à l'huile dans le bol et versez dans le moule chemisé sur environ 1 cm d'épaisseur. Faites cuire au centre du four pendant une heure, ou jusqu'à ce que le centre du gâteau soit juste ferme au toucher.","Sortez du four et laissez refroidir dans le moule 15 à 20 minutes. Transférez sur une planche à découper et découpez en formes ou en carrés."],
["Nous avons utilisé des formes d'Halloween pour la photo, mais vous pouvez simplement les couper en carrés plus traditionnels. Ou vous pouvez préparer le gâteau dans un moule plus profond et le couper en petits cubes.","La mélasse noire est riche en sucre mais a un goût fort : il en faut donc très peu pour apporter beaucoup de saveur à votre recette.",fv(0)]),
R(7897038,"Beignets de courgette et salsa","Accompagnés d'une salsa acidulée, ces beignets font un parfait accompagnement.","4","191 g",
["1 œuf, battu","1 pincée de poivre noir","15 g de parmesan, très finement râpé","50 g de farine complète","½ c. à café de levure chimique","2 courgettes, râpées","4 oignons nouveaux, finement émincés (en réserver 1 c. à soupe pour servir)","2 c. à café d'huile de colza","Pour la salsa§10 feuilles de menthe fraîche, finement hachées","Pour la salsa§3 tomates, hachées","Pour la salsa§½ oignon rouge, finement haché","Pour la salsa§½ c. à café de graines de cumin","Pour la salsa§1 bonne pincée de poivre noir","Pour la salsa§Jus d'1 citron vert frais"],
["Mettez l'œuf battu, le poivre, le parmesan, la farine et la levure dans un bol et mélangez bien.","Incorporez la courgette et l'oignon nouveau (en réservant 1 c. à soupe pour servir).","Versez l'huile dans une grande poêle antiadhésive, déposez-y 1 c. à soupe de préparation et aplatissez légèrement pour former un beignet d'environ ¾ à 1 cm d'épaisseur, en répétant par fournées jusqu'à épuisement de la préparation. (Selon la taille de votre poêle, vous devriez pouvoir cuire 3 à 4 beignets à la fois.) Au fur et à mesure qu'ils sont prêts, déposez les beignets sur une assiette et réservez.","Faites cuire les beignets 2 à 3 minutes, jusqu'à ce qu'ils soient légèrement dorés, puis retournez-les et faites cuire l'autre face (là encore 2 à 3 minutes).","Pendant ce temps, mettez tous les ingrédients de la salsa dans un bol. Mélangez bien et réservez.","Lorsque tous les beignets sont prêts, parsemez-les de l'oignon nouveau restant et servez avec la salsa. (Vous pouvez servir les beignets chauds ou froids.)"],
["Pour une alternative végétarienne au parmesan, remplacez-le par un fromage à pâte dure de type végétarien.",fv(1)]),
R(7897849,"Fish and chips aux petits pois, version géniale","Cette version est tout aussi savoureuse et plus saine que celle du fish and chips.","2","520 g",
["2 grosses pommes de terre (400 g), coupées en gros bâtonnets et précuites 5 minutes à l'eau","2 c. à café d'huile de colza + 1 c. à café pour le poisson","2 morceaux de filet de poisson blanc de 200 g, au choix","2 c. à café bombées de farine ordinaire","200 g de petits pois surgelés","2 c. à café de sauce tartare","2 c. à café de yaourt allégé","quartiers de citron et poivre noir fraîchement moulu, pour servir"],
["Préchauffez le four à 220 °C (th. 7).","Enrobez les frites précuites de 2 c. à café d'huile et poivrez généreusement. Étalez les frites sur une plaque de cuisson antiadhésive et faites cuire 25 à 30 minutes, jusqu'à ce qu'elles soient dorées et tendres.","Pendant ce temps, mettez les filets de poisson sur une assiette et farinez-les, en veillant à ce qu'ils soient bien enrobés.","Chauffez une poêle antiadhésive à feu moyen et ajoutez la c. à café d'huile restante, en l'étalant dans la poêle avec du papier absorbant.","Secouez l'excès de farine et déposez délicatement les filets de poisson dans la poêle, puis faites-les cuire 3 à 4 minutes de chaque côté.","Faites chauffer les petits pois dans une petite casserole d'eau bouillante, égouttez, puis écrasez grossièrement. Mélangez la sauce tartare et le yaourt.","Servez le poisson, les frites, les petits pois et la sauce tartare avec un tour de moulin de poivre noir, un quartier de citron et une garniture de salade."],
["Fariner le poisson avant de le faire frire empêche la surface du poisson de brûler.","Pour plus de saveur, vous pouvez assaisonner la farine : simplement du sel et du poivre, ou des épices comme le cinq-épices chinois ou le paprika fumé.","Utilisez de la farine fine de pois chiches pour une alternative sans gluten.",fv(1)]),
R(7900276,"Soupe de bœuf et d'orge","Ce n'est pas seulement une soupe : c'est un repas copieux idéal pour les jours d'hiver, entièrement cuit dans une seule casserole.","4","441 g",
["1 c. à café d'huile de colza","2 gros oignons, finement hachés","250 g de bœuf haché maigre (5 % de matières grasses)","2 gousses d'ail, écrasées","2 carottes, hachées","1 petit rutabaga, finement haché","1 poireau moyen, finement haché","2 branches de céleri, hachées","20 g de farine ordinaire","1 cube de bouillon de bœuf pauvre en sel, dissous dans 1,5 L d'eau","50 g d'orge perlé","½ c. à café de thym séché","1 pincée de poivre","2 c. à café de ciboulette hachée, pour la garniture"],
["Chauffez l'huile de colza dans une casserole, ajoutez les oignons, puis faites cuire doucement 5 minutes en remuant régulièrement.","Ajoutez le bœuf haché et remuez 5 minutes, jusqu'à ce qu'il commence à dorer, en défaisant les paquets avec une cuillère en bois.","Ajoutez l'ail, les carottes, le rutabaga, le poireau et le céleri et faites cuire 5 minutes en remuant régulièrement.","Saupoudrez la viande hachée et les légumes de farine en mélangeant bien. Incorporez le bouillon de bœuf.","Mélangez à nouveau, ajoutez l'orge perlé, le thym et le poivre, portez à ébullition, baissez le feu, couvrez, puis laissez mijoter doucement 30 minutes. Servez parsemé de ciboulette."],
["Vous pouvez préparer cette soupe avec de l'agneau haché, ou utiliser de la dinde hachée pour un plat plus pauvre en matières grasses.","Pour une version végétalienne, remplacez le bœuf par une boîte de lentilles vertes et un cube de bouillon de légumes pauvre en sel.","Pour concentrer davantage les saveurs, vous pouvez cuire sans couvercle afin de réduire la quantité de liquide.",FRZ+"peut être congelé une fois cuit. Peut être congelé dans de petits pots pour des portions individuelles. Décongelez au micro-ondes ou sur la cuisinière, à feu très doux, jusqu'à ce que ce soit bien chaud.",fv(3)]),
R(7900398,"Quesadillas épicées aux haricots","Des haricots et des légumes épicés dans des sandwichs de tortillas complètes croustillantes.","2","304 g",
["2 tortillas complètes","1 c. à soupe de purée d'amande","½ boîte de haricots pinto, grossièrement écrasés","1 c. à soupe de concentré de tomate","80 g de petits pois surgelés, décongelés et grossièrement écrasés","½ c. à café de cumin moulu","½ c. à café d'origan","½ c. à café de piment en poudre doux","2 oignons nouveaux, finement hachés","1 tomate, finement hachée","½ poivron vert, finement haché","1 c. à soupe de coriandre fraîche, grossièrement hachée, plus un peu pour servir","1 c. à soupe d'oignon rouge finement haché, pour servir"],
["Tartinez légèrement les tortillas de purée de fruits à coque.","Mélangez tout le reste, sauf l'oignon rouge, et étalez sur une tortilla, puis posez l'autre tortilla dessus.","Faites cuire dans une poêle antiadhésive à feu doux (sans huile) jusqu'à ce que la tortilla dore et devienne croustillante.","Retournez la tortilla et faites cuire l'autre face (3 à 5 minutes de chaque côté).","Déposez sur une planche et coupez en parts, puis parsemez d'oignon rouge et de coriandre. Servez avec de la salade."],
["Vous pouvez préparer les tortillas à l'avance et les faire frire au moment de les manger.",fv(2)]),
R(7902347,"Tajine marocain de courge et d'aubergine","Une version végétarienne du classique nord-africain, pleine de légumes-racines copieux et rassasiants.","4","496 g",
["2 c. à café d'huile de colza","2 oignons rouges, hachés","2 aubergines, coupées en gros morceaux","1 courge butternut moyenne, épluchée, épépinée et coupée en cubes (750 g)","6 gousses d'ail, écrasées","1 morceau de gingembre de 5 cm","1 à 2 piments (selon votre goût, forts ou doux), finement hachés","200 ml d'eau","1 boîte de 400 g de tomates concassées","2 c. à café de cannelle","1 c. à café de curcuma","2 c. à café de cumin","1 quartier de citron vert, pour servir"],
["Versez l'huile dans une casserole, ajoutez l'oignon et remuez 3 à 4 minutes, jusqu'à ce qu'il commence juste à dorer.","Ajoutez ensuite l'aubergine et la courge butternut. Faites chauffer 3 à 4 minutes en remuant régulièrement.","Ajoutez l'ail, le gingembre et le piment et faites cuire 1 à 2 minutes, en remuant toujours régulièrement.","Ajoutez la cannelle, le curcuma et le cumin. Mélangez bien, versez l'eau, remuez, puis ajoutez les tomates.","Mélangez bien et portez à ébullition douce. Baissez le feu, couvrez et laissez mijoter 15 minutes, jusqu'à ce que la courge soit tendre.","Mélangez et servez avec de la coriandre fraîche, ainsi que quelques quartiers de citron."],
["Si vous n'avez pas de courge butternut, essayez des patates douces ou un mélange d'autres légumes-racines, comme la carotte, le panais et le rutabaga.",fv(6)]),
R(7903857,"Œufs au four","Des poireaux crémeux et des champignons cuits au four avec des œufs : un petit-déjeuner savoureux, simple mais original.","4","136 g",
["1 c. à café d'huile de colza","1 poireau (160 g), finement émincé","160 g de champignons, émincés","2 c. à soupe de yaourt à la grecque à 0 % de matières grasses","1 bonne pincée de poivre blanc","4 œufs"],
["Préchauffez le four à 180 °C (th. 4).","Versez l'huile dans une casserole, puis ajoutez les poireaux et les champignons et faites cuire 4 à 5 minutes en remuant régulièrement.","Incorporez le yaourt et le poivre, puis répartissez le mélange dans 4 plats allant au four.","Faites un petit creux au milieu de chaque plat, puis cassez un œuf dans chacun. Faites cuire 12 à 15 minutes, ou plus selon la cuisson souhaitée des œufs."],
["Essayez d'ajouter un poivron rouge finement haché avec les poireaux et les champignons.","Ajoutez de la ciboulette hachée ou du basilic frais pour plus de saveur.","Les groupes « à risque » tels que les nourrissons, les enfants, les femmes enceintes, les personnes âgées et les personnes malades doivent éviter les œufs mollets, peu cuits ou crus, sauf s'ils ont la garantie qu'ils sont produits selon le programme d'assurance qualité Lion Code.",fv(1)]),
]
